   'dokter'=>['table'=>'dokter','alias'=>'d','pk'=>'dokter_id','prefix'=>'DK','title'=>'Data Dokter','singular'=>'Dokter','select'=>'d.*, po.nama_poli','joins'=>[['poli po','po.poli_id=d.poli_id']],'search'=>['d.dokter_id','d.nama_dokter','po.nama_poli'],'order'=>'d.created_at','active'=>'dokter','columns'=>[['dokter_id','Dokter ID'],['nama_dokter','Nama Dokter'],['nama_poli','Nama Poli']],'fields'=>[['dokter_id','Dokter ID','readonly',false,12],['nama_dokter','Nama Dokter','text',true,120],['poli_id','Poli','select',true,12,'optionsKey'=>'poli','foreign'=>'poli.poli_id']]],
   'poli'=>['table'=>'poli','alias'=>'po','pk'=>'poli_id','prefix'=>'POL','title'=>'Data Poli','singular'=>'Poli','select'=>'po.*','joins'=>[],'search'=>['po.poli_id','po.nama_poli'],'order'=>'po.created_at','active'=>'poli','columns'=>[['poli_id','Poli ID'],['nama_poli','Nama Poli']],'fields'=>[['poli_id','Poli ID','readonly',false,12],['nama_poli','Nama Poli','text',true,100]]],
   'berobat'=>['table'=>'berobat','alias'=>'b','pk'=>'no_transaksi','prefix'=>'TRX-','title'=>'Data Berobat','singular'=>'Transaksi Berobat','select'=>'b.*, p.nama_pasien, d.nama_dokter, po.nama_poli','joins'=>[['pasien p','p.pasien_id=b.pasien_id'],['dokter d','d.dokter_id=b.dokter_id'],['poli po','po.poli_id=d.poli_id']],'search'=>['b.no_transaksi','p.nama_pasien','d.nama_dokter','po.nama_poli','b.keluhan'],'order'=>'b.tanggal_berobat','active'=>'berobat','columns'=>[['no_transaksi','No. Transaksi'],['tanggal_berobat','Tanggal'],['nama_pasien','Pasien'],['nama_dokter','Dokter'],['nama_poli','Poli'],['keluhan','Keluhan'],['biaya_adm','Biaya Adm.','currency']],'fields'=>[['no_transaksi','No. Transaksi','readonly',false,20],['pasien_id','Pasien','select',true,12,'optionsKey'=>'pasien','foreign'=>'pasien.pasien_id'],['tanggal_berobat','Tanggal Berobat','date',true,10],['dokter_id','Dokter','select',true,12,'optionsKey'=>'dokter','foreign'=>'dokter.dokter_id'],['keluhan','Keluhan','textarea',true,1000],['biaya_adm','Biaya Administrasi (Rp)','number',true,12]]]
  ];
