 private function cfg(string $key): array { $all=$this->defs(); if(!isset($all[$key])) throw PageNotFoundException::forPageNotFound('Modul data tidak ditemukan.'); return $all[$key]; }
 private function builder(array $c) { $b=db_connect()->table($c['table'].' '.$c['alias'])->select($c['select']); foreach($c['joins'] as $j)$b->join($j[0],$j[1],'left'); return $b; }
 private function nextId(array $c): string { $rows=db_connect()->table($c['table'])->select($c['pk'])->get()->getResultArray();$max=0;foreach($rows as $r)if(preg_match('/(\d+)$/',(string)$r[$c['pk']],$m))$max=max($max,(int)$m[1]);return $c['prefix'].str_pad((string)($max+1),$c['table']==='berobat'?4:3,'0',STR_PAD_LEFT); }
 private function options(array $c): array {
  $out=[];foreach($c['fields'] as $f){if($f[2]!=='select')continue;if(isset($f['options'])){$out[$f[0]]=$f['options'];continue;}$key=$f['optionsKey']??'';$out[$f[0]]=[];
   if($key==='poli')$rows=db_connect()->table('poli')->orderBy('nama_poli')->get()->getResultArray();
   elseif($key==='pasien')$rows=db_connect()->table('pasien')->orderBy('nama_pasien')->get()->getResultArray();
   elseif($key==='dokter')$rows=db_connect()->table('dokter d')->select('d.dokter_id,d.nama_dokter,po.nama_poli')->join('poli po','po.poli_id=d.poli_id')->orderBy('d.nama_dokter')->get()->getResultArray();else $rows=[];
   foreach($rows as $r){$id=$key==='poli'?$r['poli_id']:($key==='pasien'?$r['pasien_id']:$r['dokter_id']);$label=$key==='poli'?$id.' — '.$r['nama_poli']:($key==='pasien'?$id.' — '.$r['nama_pasien']:$id.' — '.$r['nama_dokter'].' ('.$r['nama_poli'].')');$out[$f[0]][$id]=$label;}
  }return $out;
 }
 private function rules(array $c): array { $rules=[];foreach($c['fields'] as $f){if($f[2]==='readonly')continue;$p=[];if($f[3])$p[]='required';if(isset($f[4]))$p[]='max_length['.(int)$f[4].']';if($f[2]==='date')$p[]='valid_date[Y-m-d]';if($f[2]==='number'){$p[]='numeric';$p[]='greater_than_equal_to[0]';}if(isset($f['foreign']))$p[]='is_not_unique['.$f['foreign'].']';$rules[$f[0]]=implode('|',$p);}return $rules; }
 private function posted(array $c): array { $post=$this->request->getPost();$out=[];foreach($c['fields'] as $f)if($f[2]!=='readonly'&&array_key_exists($f[0],$post))$out[$f[0]]=is_string($post[$f[0]])?trim($post[$f[0]]):$post[$f[0]];return $out; }
 private function form(string $r,array $c,array $record,string $mode) { return view('clinic/form',['title'=>$c['title'],'activeMenu'=>$c['active'],'config'=>$c,'resource'=>$r,'record'=>$record,'mode'=>$mode,'options'=>$this->options($c),'errors'=>session()->getFlashdata('errors')??[]]); }
 public function dashboard() {
  $db=db_connect();$start=date('Y-m-01');$end=date('Y-m-d');$s=['pasien'=>$db->table('pasien')->countAllResults(),'dokter'=>$db->table('dokter')->countAllResults(),'poli'=>$db->table('poli')->countAllResults(),'berobat'=>$db->table('berobat')->countAllResults()];
  $s['bulan']=$db->table('berobat')->where('tanggal_berobat >=',$start)->where('tanggal_berobat <=',$end)->countAllResults();$s['biaya']=(float)($db->table('berobat')->selectSum('biaya_adm')->where('tanggal_berobat >=',$start)->where('tanggal_berobat <=',$end)->get()->getRowArray()['biaya_adm']??0);
  $recent=$db->table('berobat b')->select('b.*,p.nama_pasien,d.nama_dokter,po.nama_poli')->join('pasien p','p.pasien_id=b.pasien_id')->join('dokter d','d.dokter_id=b.dokter_id')->join('poli po','po.poli_id=d.poli_id')->orderBy('b.tanggal_berobat','DESC')->limit(8)->get()->getResultArray();
  return view('dashboard',['title'=>'Dashboard','activeMenu'=>'dashboard','stats'=>$s,'recent'=>$recent]);
 }
 public function index(string $r) { $c=$this->cfg($r);$q=trim((string)$this->request->getGet('q'));$b=$this->builder($c);if($q!==''){$b->groupStart();foreach($c['search'] as $i=>$f)$i===0?$b->like($f,$q):$b->orLike($f,$q);$b->groupEnd();}$rows=$b->orderBy($c['order'],'DESC')->get()->getResultArray();return view('clinic/index',['title'=>$c['title'],'activeMenu'=>$c['active'],'config'=>$c,'resource'=>$r,'rows'=>$rows,'q'=>$q]); }
 public function create(string $r) { $c=$this->cfg($r);$rec=[$c['pk']=>$this->nextId($c)];foreach($c['fields'] as $f)$rec[$f[0]]??=($f[2]==='date'?date('Y-m-d'):'');return $this->form($r,$c,$rec,'create'); }
 public function store(string $r) { $c=$this->cfg($r);if(!$this->validate($this->rules($c)))return redirect()->back()->withInput()->with('errors',$this->validator->getErrors());$d=$this->posted($c);$d[$c['pk']]=$this->nextId($c);if($c['table']==='berobat'&&isset($d['biaya_adm']))$d['biaya_adm']=(float)$d['biaya_adm'];try{db_connect()->table($c['table'])->insert($d);return redirect()->to(site_url('data/'.$r))->with('success',$c['singular'].' berhasil ditambahkan.');}catch(Throwable $e){log_message('error','Insert '.$r.': '.$e->getMessage());return redirect()->back()->withInput()->with('error','Data gagal disimpan. Periksa isian dan data relasi.');} }
 public function edit(string $r,string $id) { $c=$this->cfg($r);$rec=db_connect()->table($c['table'])->where($c['pk'],$id)->get()->getRowArray();if(!$rec)throw PageNotFoundException::forPageNotFound('Data tidak ditemukan.');return $this->form($r,$c,$rec,'edit'); }
 public function update(string $r,string $id) { $c=$this->cfg($r);if(!db_connect()->table($c['table'])->where($c['pk'],$id)->countAllResults())throw PageNotFoundException::forPageNotFound('Data tidak ditemukan.');if(!$this->validate($this->rules($c)))return redirect()->back()->withInput()->with('errors',$this->validator->getErrors());$d=$this->posted($c);if($c['table']==='berobat'&&isset($d['biaya_adm']))$d['biaya_adm']=(float)$d['biaya_adm'];try{db_connect()->table($c['table'])->where($c['pk'],$id)->update($d);return redirect()->to(site_url('data/'.$r))->with('success',$c['singular'].' berhasil diperbarui.');}catch(Throwable $e){log_message('error','Update '.$r.': '.$e->getMessage());return redirect()->back()->withInput()->with('error','Perubahan gagal disimpan. Periksa isian form.');} }
 public function delete(string $r,string $id) { $c=$this->cfg($r);try{$found=db_connect()->table($c['table'])->where($c['pk'],$id)->countAllResults();if(!$found)return redirect()->to(site_url('data/'.$r))->with('error','Data tidak ditemukan.');db_connect()->table($c['table'])->where($c['pk'],$id)->delete();return redirect()->to(site_url('data/'.$r))->with('success',$c['singular'].' berhasil dihapus.');}catch(Throwable $e){log_message('warning','Delete '.$r.': '.$e->getMessage());return redirect()->to(site_url('data/'.$r))->with('error','Data masih dipakai record lain sehingga tidak dapat dihapus.');} }
 public function show(string $r,string $id) { $c=$this->cfg($r);$row=$this->builder($c)->where($c['alias'].'.'.$c['pk'],$id)->get()->getRowArray();if(!$row)throw PageNotFoundException::forPageNotFound('Data tidak ditemukan.');return view('clinic/show',['title'=>'Detail '.$c['singular'],'activeMenu'=>$c['active'],'config'=>$c,'resource'=>$r,'row'=>$row]); }
 private function reportDefs(): array { return [
 'pasien'=>['title'=>'Laporan Data Pasien','active'=>'laporan-pasien','columns'=>[['pasien_id','Pasien ID'],['nama_pasien','Nama Pasien'],['tanggal_lahir','Tanggal Lahir'],['usia','Usia'],['jenis_kelamin','Jenis Kelamin'],['alamat','Alamat']]],
 'dokter'=>['title'=>'Laporan Dokter per Poli','active'=>'laporan-dokter','columns'=>[['dokter_id','Dokter ID'],['nama_dokter','Nama Dokter'],['poli_id','Poli ID'],['nama_poli','Nama Poli']]],
 'poli'=>['title'=>'Laporan Data Poli','active'=>'laporan-poli','columns'=>[['poli_id','Poli ID'],['nama_poli','Nama Poli'],['jumlah_dokter','Jumlah Dokter']]],
 'berobat'=>['title'=>'Laporan Transaksi Berobat','active'=>'laporan-berobat','columns'=>[['no_transaksi','No. Transaksi'],['pasien_id','Pasien ID'],['nama_pasien','Nama Pasien'],['usia','Usia'],['jenis_kelamin','Jenis Kelamin'],['keluhan','Keluhan'],['nama_poli','Nama Poli'],['nama_dokter','Dokter'],['biaya_adm','Biaya Administrasi','currency']]],
 'biaya'=>['title'=>'Rekap Biaya Administrasi','active'=>'laporan-biaya','columns'=>[['tanggal_berobat','Tanggal'],['no_transaksi','No. Transaksi'],['nama_pasien','Nama Pasien'],['nama_poli','Poli'],['nama_dokter','Dokter'],['biaya_adm','Biaya Administrasi','currency']]]; }
 private function reportData(string $t): array {
  $d=$this->reportDefs();if(!isset($d[$t]))throw PageNotFoundException::forPageNotFound('Laporan tidak ditemukan.');$db=db_connect();$q=trim((string)$this->request->getGet('q'));
  if($t==='pasien'){$b=$db->table('pasien p')->select('p.pasien_id,p.nama_pasien,p.tanggal_lahir,TIMESTAMPDIFF(YEAR,p.tanggal_lahir,CURDATE()) AS usia,p.jenis_kelamin,p.alamat');if($q!=='')$b->groupStart()->like('p.pasien_id',$q)->orLike('p.nama_pasien',$q)->orLike('p.alamat',$q)->groupEnd();$rows=$b->orderBy('p.nama_pasien')->get()->getResultArray();}
  elseif($t==='dokter'){$b=$db->table('dokter d')->select('d.dokter_id,d.nama_dokter,d.poli_id,po.nama_poli')->join('poli po','po.poli_id=d.poli_id');if($q!=='')$b->groupStart()->like('d.dokter_id',$q)->orLike('d.nama_dokter',$q)->orLike('po.nama_poli',$q)->groupEnd();$rows=$b->orderBy('po.nama_poli')->orderBy('d.nama_dokter')->get()->getResultArray();}
  elseif($t==='poli'){$b=$db->table('poli po')->select('po.poli_id,po.nama_poli,COUNT(d.dokter_id) AS jumlah_dokter')->join('dokter d','d.poli_id=po.poli_id','left')->groupBy('po.poli_id,po.nama_poli');if($q!=='')$b->groupStart()->like('po.poli_id',$q)->orLike('po.nama_poli',$q)->groupEnd();$rows=$b->orderBy('po.nama_poli')->get()->getResultArray();}
  else{$b=$db->table('berobat b')->select('b.no_transaksi,b.tanggal_berobat,b.pasien_id,p.nama_pasien,TIMESTAMPDIFF(YEAR,p.tanggal_lahir,b.tanggal_berobat) AS usia,p.jenis_kelamin,b.keluhan,po.nama_poli,d.nama_dokter,b.biaya_adm')->join('pasien p','p.pasien_id=b.pasien_id')->join('dokter d','d.dokter_id=b.dokter_id')->join('poli po','po.poli_id=d.poli_id');$start=(string)$this->request->getGet('start');$end=(string)$this->request->getGet('end');$poli=(string)$this->request->getGet('poli_id');$doc=(string)$this->request->getGet('dokter_id');$pas=(string)$this->request->getGet('pasien_id');if($start!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$start))$b->where('b.tanggal_berobat >=',$start);if($end!==''&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$end))$b->where('b.tanggal_berobat <=',$end);if($poli!=='')$b->where('d.poli_id',$poli);if($doc!=='')$b->where('b.dokter_id',$doc);if($pas!=='')$b->where('b.pasien_id',$pas);if($q!=='')$b->groupStart()->like('b.no_transaksi',$q)->orLike('p.nama_pasien',$q)->orLike('d.nama_dokter',$q)->orLike('b.keluhan',$q)->groupEnd();$rows=$b->orderBy('b.tanggal_berobat','DESC')->get()->getResultArray();}
  return ['definition'=>$d[$t],'rows'=>$rows,'type'=>$t];
 }
 public function report(string $t='berobat') {$x=$this->reportData($t);$sum=0;if(in_array($t,['berobat','biaya'],true))foreach($x['rows'] as $row)$sum+=(float)($row['biaya_adm']??0);$f=['start'=>(string)$this->request->getGet('start'),'end'=>(string)$this->request->getGet('end'),'poli_id'=>(string)$this->request->getGet('poli_id'),'dokter_id'=>(string)$this->request->getGet('dokter_id'),'pasien_id'=>(string)$this->request->getGet('pasien_id')];return view('reports/index',['title'=>$x['definition']['title'],'activeMenu'=>$x['definition']['active'],'type'=>$t,'definition'=>$x['definition'],'rows'=>$x['rows'],'total'=>$sum,'q'=>(string)$this->request->getGet('q'),'filters'=>$f,'poliOptions'=>db_connect()->table('poli')->orderBy('nama_poli')->get()->getResultArray(),'dokterOptions'=>db_connect()->table('dokter')->orderBy('nama_dokter')->get()->getResultArray(),'pasienOptions'=>db_connect()->table('pasien')->orderBy('nama_pasien')->get()->getResultArray()]);}
 public function export(string $t='berobat') {$x=$this->reportData($t);$s=fopen('php://temp','r+');fwrite($s,"\xEF\xBB\xBF");fputcsv($s,array_column($x['definition']['columns'],1),';');foreach($x['rows'] as $row){$line=[];foreach($x['definition']['columns'] as $c){$v=$row[$c[0]]??'';if(($c[2]??'')==='currency')$v=number_format((float)$v,0,',','.');$line[]=$v;}fputcsv($s,$line,';');}rewind($s);$csv=stream_get_contents($s);fclose($s);return $this->response->setHeader('Content-Type','text/csv; charset=UTF-8')->setHeader('Content-Disposition','attachment; filename="laporan-'.$t.'-'.date('Ymd-His').'.csv"')->setBody($csv);}
}
